const { LRUCache } = require('./src/lru');
const assert = require('node:assert/strict');
// capacity validation
for (const bad of [0, -1, 1.5, Infinity, NaN, '3', undefined, null, {}]) {
  assert.throws(() => new LRUCache(bad), RangeError, JSON.stringify(bad));
}
assert.ok(new LRUCache(1));
// undefined-value get refreshes recency
const c = new LRUCache(2);
c.set('a', undefined).set('b', 2);
assert.equal(c.get('a'), undefined);
c.set('c', 3);
assert.equal(c.has('a'), true);
assert.equal(c.has('b'), false);
// update existing does not evict unrelated or grow
c.set('a', 1);
assert.equal(c.size, 2);
assert.equal(c.has('c'), true);
// arbitrary key types, Map semantics
const k = {}; const c2 = new LRUCache(3);
c2.set(k, 'obj').set(NaN, 'nan').set(1, 'one');
assert.equal(c2.get(k), 'obj');
assert.equal(c2.get(NaN), 'nan');
assert.equal(c2.get(1), 'one');
assert.notEqual(c2.get('1'), 'one');
// independence
const a1 = new LRUCache(1), a2 = new LRUCache(1);
a1.set('x', 1);
assert.equal(a2.has('x'), false);
// capacity 1 eviction on update-to-existing keeps it
const s = new LRUCache(1);
s.set('x', 1); s.set('x', 2);
assert.equal(s.get('x'), 2); assert.equal(s.size, 1);
console.log('extra checks passed');
"

